INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(352200, 0, 3522, 0, 0, 0, 'Blade''s Edge Mountains', 'The Blade''s Edge Mountains are a maze of red canyons in the north of Outland, crowned by great curving spikes of stone. This is gronn country. Gruul the Dragonkiller, who once tore the black dragonflight from the sky and left its bones on the spires, rules from his lair in the north, and his seven sons drive the Bladespire and Bloodmaul ogres against each other and everyone else. Newcomers have carved out footholds all the same: the night elves at Sylvanaar, Toshley''s gnomes on the Razor Ridge, the Horde in Thunderlord Stronghold and the Cenarion Expedition at Evergrove, while the half-ogre Mok''Nathal hold out in the east. Arakkoa cults whisper of a coming raven, the Wyrmcult worships the surviving black dragons, and the Burning Legion has raised forge camps on the high terraces, where ogres made wise by strange crystals have found a refuge of their own at Ogri''la.', 'warcraft.wiki.gg/wiki/Blade''s_Edge_Mountains (gronn control the ogres; Wyrmcult worships the remaining black dragons; Ogri''la); warcraft.wiki.gg/wiki/Gruul (dragons impaled on the spires, Dragons'' End); quest 10504 description (Gruul and his seven sons); quest 10607 reward text; npc_text 10926 (Chu''a''lor)'),
(352201, 1, 3522, 1, 0, 0, 'Sylvanaar', 'Sylvanaar is a night elf town in the southwest of the mountains, raised in a short time by elven magic on land its founders found empty. Around it they are coaxing the Living Grove to grow at an unnatural pace, meant to ring the town with a defensive woodland of tranquil beauty. Fey drakes pollinate the grove, treant defenders can be called up from its seedlings, and an ancient of war named Stronglimb Deeproot stands as its chief protector. Commander Skyshadow leads the town, wary of the ogres in the ravine below and of the Horde beyond it. To the south, a tunnel through Blade Tooth Canyon is Sylvanaar''s lifeline to the Harborage in the swamps of Zangarmarsh.', 'warcraft.wiki.gg/wiki/Sylvanaar (night elf settlement in the Living Grove); quest 10487 description (elven magics grew a town and grove in a short time); quest 10504 reward text (land initially found empty); quests 10455, 10456, 10457; quest 10489 (Stronglimb Deeproot, chief defender of the Living Grove); quest 10502 description; quest 10927 description and reward (tunnel, lifeline to the swamp, trade with the Harborage); npc_text 10264 (Skyshadow)'),
(352202, 1, 3522, 2, 0, 0, 'Veil Lashh', 'South of the Living Grove, the Lashh''an arakkoa roost among the trees of Veil Lashh, where tame kaliri flutter about their nests. Their magic unsettles the night elves next door. The Lashh''an tear out clawfuls of their own feathers as reagents and keep tomes of crude pictographs high in the branches. Their rites are worked at circles of power on the ground, and those who have dared to try one describe neither a curse nor a conjuring, but a kind of communion that fills the caster with the spirit of a kaliri. At Sylvanaar, Rina Moonspring suspects that the Lashh''an are behind the grove''s lynxes turning on the town.', 'quest 10555 description and request text (feathers as reagents, spellbooks high in the trees); quest 10556 description and reward text (kaliri spirit, communion spell); quest 10455 description (arakkoa of Veil Lashh suspected); DB spawns: Tame Kaliri, Lashh''an Tome, kneel targets and spell origin in area 3782'),
(352203, 1, 3522, 3, 0, 0, 'Bloodmaul Outpost', 'Bloodmaul Ravine cuts between Sylvanaar and Thunderlord Stronghold, and toward its southern end the Bloodmaul clan holds Bloodmaul Outpost, watched over by the Northmaul and Southmaul towers. The Bloodmaul are known for their brew, a foul swill their brewmasters carry about in barrels and their warriors practically live on. A troll witch doctor named T''chali taught them the craft, and they repaid him by burying him in the ravine. At the far south lies the Draenethyst Mine, where crystals grow naturally from the walls and the Explorers'' League wants samples. The Bloodmaul keep plunder there too: a Thunderlord spear, the Thunderspike, stolen from the Bladespire, was hidden at the back of the mine.', 'quests 10502, 10511 (brewmasters carry the brew to the other ogres), 10512; quest 10542 description (T''chali taught the Bloodmaul to brew, buried); quest 10510 description (Draenethyst Mine at the south end, crystals grow naturally); quest 10525 reward and 10526 description (Thunderspike stolen from the Bladespire, back of the mine); quest 10518 (Northmaul Tower); quest 10543 (Grimnok atop the Southmaul Tower); DB: T''chali 21349 stands in area 3824 Bloodmaul Ravine'),
(352204, 1, 3522, 4, 0, 0, 'Thunderlord Stronghold', 'Thunderlord Stronghold was the seat of the Thunderlord clan until those orcs were made fel orcs by the blood of Mannoroth and abandoned it. The Bladespire ogres moved into the empty halls, and the Horde has since driven them out and holds the town in the old clan''s name. Its warriors still fight ogres on every side, and the scholar Rokgah Bloodgrip hunts the clan''s lost relics to appease its restless dead. The Horde''s dire wolves den on the Jagged Ridge to the south under Rema, the den mother, sharing the slopes with bloodletters that eat and breed without pause. The tunnel of Blades'' Run carries trade to Swamprat Post in Zangarmarsh, and Rexxar has come here seeking his people.', 'warcraft.wiki.gg/wiki/Thunderlord_Stronghold (abandoned after the fel transformation, Bladespire occupation, Horde holds it in honor of the clan, dire wolves under Rema at Jagged Ridge, Rexxar came seeking his race); quest 10486 description; quest 10503 description; quest 10456 description (the Horde brought dire wolves); quest 10690 (Rema); npc_text 10322 (Rokgah); quest 10526 request text (appease the dead spirits); quest 10928 (tunnel, trade with Swamp Rat)'),
(352205, 1, 3522, 5, 0, 0, 'Bladespire Hold', 'Bladespire Hold, down in the ravine west of Thunderlord Stronghold, is the seat of the strongest ogre clan in the mountains. The Bladespire stand highest in the favor of Gruul the Dragonkiller, a place won for them by their crafty chieftain Gorr''Dim, and they keep packs of raptors alongside their brutes and shamans. They once held Thunderlord Stronghold, and the Thunderlord relics lost when the Horde drove them out, a drum, an arrow and a tablet, now lie somewhere in the hold. Gorr''Dim keeps defenders about him who are sworn never to touch the Bloodmaul brew. In a cage at the heart of the hold sits Vindicator Vuuleen of Sylvanaar, who insists he is exactly where he wants to be.', 'quest 10503 description (west, the ones defeated to take the stronghold; ogres and raptors); quest 10504 description (strongest clan, favor of Gruul); quest 10517 description (Gorr''Dim elevated his clan, sober defenders); npc_text 10322 and quest 10524 (drum, arrow, tablet in Bladespire Hold); npc_text 10300 and quest 10516 (Vuuleen wants to stay in the cage); DB spawns: Bladespire Brute, Shaman, Raptor, Sober Defender in 3773'),
(352206, 1, 3522, 6, 0, 0, 'Toshley''s Station', 'When the night elves of Sylvanaar sent the gnome Toshley and his followers away over their machines and experiments, the gnomes climbed to the Razor Ridge and built Toshley''s Station, where they can experiment as they please. The station is a clutter of laboratories and launch gear, from the Zapnabber twins'' Zephyrium Capacitorium, which flings willing volunteers across the mountains, to a scientist who studies both time and sound. Razak''s Roughriders, hired to protect the scientists, man the defense guns against the ravagers that swarm the ridge. To the north, at the ridge''s southwestern edge, Bladespire ogres at the Bladespire Outpost raid the station''s power converters, and the gronn Maggoc, warden of the eastern mountains, prowls nearby.', 'warcraft.wiki.gg/wiki/Toshley''s_Station (left Sylvanaar over machines and experiments, built to experiment as they wish, Razak''s Roughriders); quest 10580 description; quest 10581 objective (up the ramp to the Razor Ridge); quests 10557, 10710 (Tally and Rally Zapnabber, Zephyrium Capacitorium); npc_text 10444 (Nickwinkle studies time and sound); npc_text 10469 and creature_text 21118 (assault by the bugs, def guns); quest 10620 description; quest 10584 description (Bladespire Outpost to the north raids power converters); quest 10843 (Bladespire Outpost at the southwestern edge of the Razor Ridge); quest 10996 description (Maggoc, warden of the eastern mountain range); DB: Maggoc 20600 stands in area 3922'),
(352207, 1, 3522, 7, 0, 0, 'Singing Ridge', 'The Singing Ridge is a field of great crystals in the south of the mountains, their shards humming with harmonies that one gnome scholar suspects are a sign of life, perhaps bound in some way to the nether drakes that nest there. The drakes are a strange inheritance. Their eggs were once black dragon eggs, changed by the wave of nether energy that washed over the land when Draenor blew apart. Dreadwing, their brood mother, dwells on the ridge, and crystal flayers scratch away at the shards. To the north, the Scalewing Shelf belongs to serpents whose breath crackles with lightning and to ridgespine stalkers that drop on passersby from the rocks.', 'quest 10594 reward text (crystals almost alive, symbiosis with the nether drakes); quest 10608 description; quest 10609 request text (eggs used to be black dragon eggs, changed when Draenor blew apart); quest 10853 description; quest 10845 description (Dreadwing, brood mother); quest 10657 description (Scalewing serpents, lightning breath); quest 10620 description (ridgespine stalkers)'),
(352208, 1, 3522, 8, 0, 0, 'Veil Vekh', 'In the southeastern canyons the Vekh''nir arakkoa keep Veil Vekh. For years they troubled no one, but something has stirred them: a strange religion holds them in a frenzy, and they now carry crystals that they charge at their spell circles for some dark purpose. Nearby, in the caverns of Trogma''s Claim, the Vekh''nir keep captured ogres as slaves under the watch of their leader, Vekh. Beside the veil, silkwing larvae spin their cocoons across Vekhaar Stand, prized by the Mok''Nathal for their silk and iridescent wings, and a tunnel from the stand leads into Death''s Door.', 'quest 10565 description and request text (benign for many years, now stirred; crystals infused at spell circles); quest 10566 (ogre slaves at Trogma''s Claim); quest 10846 description (Vekh''nir enslaved ogres at Trogma''s Claim, Vekh); quests 10617, 10618 (silkwing cocoons and wings); quest 10910 description (Vekhaar Stand, tunnel into Death''s Door); DB spawns: Silkwing Larva in 3827, Arakkoa Egg in 3783'),
(352209, 1, 3522, 9, 0, 0, 'Mok''Nathal Village', 'Mok''Nathal Village lies in the east of the mountains, where the Mok''Nathal still survive: a people of mixed orc and ogre blood, once honored by orc shamans before the clans fell to demonic corruption. Their hunters keep tame clefthoof and quilbeasts, the silk and wings of the canyon silkwings are worked into their crafts, and Matron Varah offers any wanderer a place at the village fires. The spiritcallers keep the memory of the ancestors alive in flame. Enemies press in from every side, from the Bladespire Outpost to the west, the Vekh''nir to the south and the nether drakes of the Singing Ridge, and the village chief, Leoroxx, measures every outsider by a harsh standard.', 'warcraft.wiki.gg/wiki/Blade''s_Edge_Mountains (Mok''Nathal honored by shamans before the demonic corruption, small village); DB spawns: Tame Clefthoof, Quilbeast, Mok''Nathal Hunter in 3844; quests 10617, 10618; npc_text 10249 (Matron Varah); npc_text 10647 (Dohgar: flame of their memory); quests 10843, 10845, 10846; npc_text 10645 (Leoroxx)'),
(352210, 1, 3522, 10, 0, 0, 'Death''s Door', 'Death''s Door is a canyon south of Mok''Nathal Village, reached through a tunnel from Vekhaar Stand, where the Burning Legion holds open a portal onto the world in which it breeds its hounds. Baelmon the Hound-Master maintains the ritual that keeps the portal alive at the canyon''s north end, and those who come through are sent on by translocator to Forge Camp: Wrath. Two warp-gates, one in the north and one in the south, serve to move and empower the void terrors, each within range of a fel cannon, while deathforge smiths and technicians tend the guns. To the druids of Evergrove it is the gravest danger the Legion poses in the mountains.', 'quest 10910 description (portal onto the world where the Legion breeds its hounds; route via Vekhaar Stand, south of Mok''Nathal); quest 10912 description (Baelmon maintains the ritual, north end); quest 10911 description (two warp-gates, teleportation and enhancement of void terrors, fel cannons); quest 10904 description; creature_text 19747 (translocator, Forge Camp Wrath awaits)'),
(352211, 1, 3522, 11, 0, 0, 'Razaan''s Landing', 'Razaan''s Landing, north of the Razor Ridge, is a camp of Razaani ethereals under Nexus-Prince Razaan. Their devices give off small pink orbs of light that drift above the landing like ornaments, and fiendling flesh beasts, some of them crackling with ether, wander among them. Neighbors from the gnome station and the Mok''Nathal village learned the truth the hard way. The orbs are made of nether energy and captured souls, among them the souls of gnomes who vanished on the road north and of Mok''Nathal ancestors.', 'quest 10674 description (pink floating light orbs, probably only decoration); quest 10675 description (nether energy and souls, gnome souls; Nexus-Prince Razaan); quest 10671 description (fiendling flesh beasts, ether-energized flesh); quest 10859 description; quest 10865 description (some of them Mok''Nathal); quest 10620 request text (people who headed north disappeared)'),
(352212, 1, 3522, 12, 0, 0, 'Dragons'' End', 'Dragons'' End is a valley of old bones. Here the gronn and the Bladespire clan brought down the black dragons Deathwing had left on Draenor, and Gruul impaled their bodies on the spires, where the remains still hang. At the eastern edge lies the Cursed Hollow, lair of the gronn Grulloc, who guards a sack and a dragon skull from his father''s slaughter of the flight, and who cannot resist chasing a pig. Southwest of the Circle of Blood, the Churning Gulch seethes with crust bursters, among the most poisonous creatures in all of Outland, whose glands a certain alchemist values highly.', 'warcraft.wiki.gg/wiki/Gruul (Bladespire incantations, dragons impaled on the spires, bones at Dragons'' End); quest 10721 description (Cursed Hollow on the eastern edge of Dragons'' End, Huffer chased); quest 10800 description; quest 10995 description (dragon skull from his father''s slaying of the black dragonflight); creature_text 20216 (Me keep piggy as pet); quest 10715 description (Churning Gulch southwest, crust bursters most poisonous creatures); quest 10787 (deprecated) description (dragon corpses impaled upon the rocks at Dragons'' End); quest 10724 reward text (head of a black dragon from Dragons'' End)'),
(352213, 1, 3522, 13, 0, 0, 'Circle of Blood', 'The Circle of Blood is a great ogre structure in Daggermaw Canyon, raised around an arena where challengers meet one another in combat. Goblin organizers and merchants have set up their stalls at its gates. The towers just outside see quieter business. Atop the eastern one stands Mog''dorg the Wizened, an old Bloodmaul ogre who speaks with surprising clarity, and Chort, below, sends trusted visitors up to him with a warning to keep quiet. Nearby, a sharp-tongued alchemist who calls himself Baron Sablemane receives guests with a black whelp at his side.', 'warcraft.wiki.gg/wiki/Circle_of_Blood (large ogre structure holding the arena, in Daggermaw Canyon); DB spawns in 3775: Steamwheedle Sam <Arena Organizer>, arena vendors, Mog''dorg 22941, Chort 22995, Baron Sablemane 22103, Blackwhelp 22108; quest 11057 (tower on the eastern side of the arena); quest 10989 description; npc_text 10877 (Chort); npc_text 10860 (Mog''dorg''s clarity); quest 10783 description'),
(352214, 1, 3522, 14, 0, 0, 'Bloodmaul Camp', 'North of the Circle of Blood, Daggermaw Canyon runs on toward Gruul''s Lair, and along it the Bloodmaul have pitched Bloodmaul Camp. Here the clan plans its offensive against Sylvanaar and the Ruuan Weald under the chieftain Dorgok, and here its maulers, warlocks and battle worgs gather around kegs of grog, moonshine and seed beer. Down in the canyon, Bloodmaul taskmasters and soothsayers meet to talk over their gronn masters'' orders, a den of marmots burrows among the rocks, and Bladespire enforcers patrol the stretch nearest the lair while Expedition wardens watch from the canyon''s edge.', 'quest 10795 description (attacks on Sylvanaar and Ruuan Weald staged from Bloodmaul Camp, Dorgok); quest 10784 / 10796 (maulers and warlocks); DB spawns: Bloodmaul Battle Worg, Green Spot Grog Keg, Ripe Moonshine Keg, Fermented Seed Beer Keg in 3777; quest 10720 description (marmot den in Daggermaw Canyon past the Circle of Blood); quest 10714 (taskmaster and soothsayer in conversation; sons of Gruul); DB spawns in 3826: Bladespire Enforcer, Expedition Warden'),
(352215, 1, 3522, 15, 0, 0, 'Gruul''s Lair', 'The road through Daggermaw Canyon ends at Gruul''s Lair, home of Gruul the Dragonkiller and of High King Maulgar, the old ogre king who serves him. Gruul trusts the approach only to the toughest of the Bladespire, enforcers, battlemages and ravagers led by Fingrom, and in their encampment outside the lair Rexxar''s wyvern Leokk was kept caged. Before the entrance stands the altar of Goc, master of the Bladespire. On the right of the road, just short of the lair, lies Soulgrinder''s Barrow, where the gronn Skulloc Soulgrinder keeps himself hidden from the world.', 'quest 10805 description (Gruul protects the exterior with the toughest ogres, Fingrom); quest 10724 description (Leokk caged in the Bladespire encampment outside Gruul''s Lair); quest 10742 description (Goc''s altar outside Gruul''s Lair); quest 10806 description (Goc, master of the Bladespire); quest 11000 description and reward text (barrow on the right before Gruul''s Lair; Gruul and his puppet, the old king, Maulgar); quest 10998 description (Skulloc keeps himself hidden); DB spawns in 3774: Bladespire Enforcer, Battlemage, Ravager, Fingrom 20757, Leokk 22268, Meeting Stone'),
(352216, 1, 3522, 16, 0, 0, 'Evergrove', 'Evergrove is the Cenarion Expedition''s haven in the Ruuan Weald, kept almost entirely by night elves and open to Alliance and Horde alike. Tree Warden Chawn leads the druids'' effort to restore the balance of nature here, helped by scholars such as Timeon, who studies the arakkoa, and a gnome who wonders whether the druids hide batteries under their robes. The ancient Mosswood rests here before his long sleep. The weald around the grove is being cut and hunted bare by Wyrmcult hewers and poachers, the Ruuan''ok arakkoa raise their Harbingers of the Raven at Veil Ruuan to the north, and Watcher Moonshade holds the Wyrmskull Bridge to the west.', 'warcraft.wiki.gg/wiki/Evergrove (Cenarion outpost in Ruuan Weald, manned almost entirely by night elves, services to both factions, Chawn leader); npc_text 10534 (Chawn: reestablish the balance of nature); quest 10615 reward text (Timeon); npc_text 10554 (O''Mally: batteries under those robes); npc_text 10640 (Mosswood: soon I will plant roots and sleep); quests 10682, 10713, 10717 (hewers, poachers); quest 10567 description (Ruuan''ok Harbingers of the Raven); npc_text 10667 and quest 10894 (Watcher Moonshade at Wyrmskull Bridge)'),
(352217, 1, 3522, 17, 0, 0, 'Forge Camp: Anger', 'On the eastern heights the Burning Legion works Forge Camp: Anger, where doomforge engineers and attendants labor at fel cannons under the eye of anger guards and a ring of Legion obelisks. Its masters give orders through a Legion communicator, and the demon on the far end suspects his underling Doomcryer of undermining him. Just north of the camp, fel corrupters spread their taint through the Bladed Gulch, turning its scalewings and daggermaws into felsworn beasts. Farther north lies Skald, a scorched land of ash and searing elementals. A great wood flourished there until the Legion sent imps of flame to burn it away, and Mosswood the Ancient is the last of its people.', 'quest 10819 description (east of Evergrove, Legion communicator); quests 10820, 10821 (Doomforge attendants and engineers, Doomcryer undermining his authority, five obelisks, anger guards); DB spawns in 3787: Legion Fel Cannon, Anger Guard, Legion Obelisk; quest 10753 description (corruption spreading across Bladed Gulch, Fel Corrupters, Felsworn); quest 10770 description (great wood burned by imps sent by the Legion); quest 10771 description (only I remain); DB spawns in 3866: Searing Elemental, Scorch Imp, Fertile Volcanic Soil'),
(352218, 1, 3522, 18, 0, 0, 'Blackwing Coven', 'The Blackwing Coven is the cavernous stronghold of the Wyrmcult, at the end of the road that runs west past Grishnath and the Raven''s Wood. Its humans, orcs, draenei and Broken seek the power of the surviving black dragons, and in its depths they raise blackwhelps among clutches of eggs. Their patriarch is Maxnar the Ashmaw, one of the dragonkin, and his second, Kolphis Darkscale, drives his overseers hard for lumber and livestock from the weald. The cult is at war with the Boulder''mok ogres, and Kolphis has arranged a truce with the arakkoa. Its fighters mass in the Wyrmskull Tunnel under Draaca Longtail, ready to fall on Evergrove.', 'warcraft.wiki.gg/wiki/Wyrmcult (humans, orcs, Broken and draenei; harness the power of the black dragonflight; Blackwing Coven); quest 10722 and 10747 descriptions (route, whelps and eggs); quest 10748 description (Maxnar, dragonkin); creature_text 21983 (Kolphis second-in-command); npc_text 10541, 10543 (Kolphis: lumber and livestock, war with Boulder''mok, truce with the arakkoa); quest 10893 description (wyrmcultists massing in the tunnel, Draaca Longtail); creature_template 21389 subname Wyrmcult Patriarch; DB positions: Maxnar, Kolphis and the coven''s whelps and zealots stand at z 150 to 178, some 200 yards below the Forge Camp: Wrath demons (z 364 to 374)'),
(352219, 1, 3522, 19, 0, 0, 'Raven''s Wood', 'The Raven''s Wood spreads across the northwest, a forest of leafbeards and stonebarks watched over by Treebole, an ancient of lore who stands at a fork in the path past Grishnath. An evil has crept into its trees. The Grishna arakkoa have caused koi-koi spirits to possess the leafbeards and stonebarks, and dire ravens wheel through the branches. On the wood''s western side lies Boulder''mok, a camp of Bladespire ogres who bring sacrifices to the altar of Gorgrom the Dragon-Eater and who fight a running war with the Wyrmcult nearby.', 'quest 10829 description (Treebole, ancient of lore, fork in the path past Grishnath); quest 10830 description (Grishna, koi-koi spirits, leafbeards and stonebarks); DB spawns in 3830: Dire Raven, Raven''s Wood Leafbeard and Stonebark; quest 10803 description (west side of the Raven''s Wood); quest 10786 (Bladespire ogres of Boulder''mok); quest 10723 description (Gorgrom accepting sacrifices from the ogres of Boulder''mok); npc_text 10543 (Wyrmcult fighting the Boulder''mok ogres)'),
(352220, 1, 3522, 20, 0, 0, 'Grishnath', 'Grishnath is the roost of the Grishna arakkoa, in the north beside the Raven''s Wood. Totems left by their Oracles of the Raven stand at four shrines, and through them the faithful hear the word of their god: that the raven will rise again from the darkest night, that the faithful will take flight with it while the rest walk the ground in shame, and that the old blood will flow once more. The Grishna carry strange orbs beneath their feathers, suffused with a purple glow and pulsing to an unheard beat, and with that magic they have set evil spirits upon the trees of the neighboring wood.', 'quest 10607 description (totems of the Oracles of the Raven, the Word of the Raven); broadcast_text 19475, 19476, 19477, 19478 (prophecies); DB: First to Fourth Prophecy objects in 3781; quest 10825 description (orb from beneath the contour feathers); quest 10830 description (Grishnath orbs found throughout Grishnath; Grishna possess the trees)'),
(352221, 1, 3522, 21, 0, 0, 'Ogri''la', 'High on a western terrace, reached only by flight, lies Ogri''la, the ogre heaven that the clans below whisper about. Its ogres, many of them two-headed, have gained a keen mind from the crystals that grow around their home, and they want only to live in peace, which the demons of the forge camps, the ethereals and above all the black dragonflight will not allow. Chu''a''lor, whose two heads finish each other''s sentences, greets newcomers. Just to the north, the Sha''tari Skyguard keeps its outpost under Sky Commander Keller, who wears an eyepatch and claims he built the place with his own hands, and flies missions from it for the protection of both.', 'warcraft.wiki.gg/wiki/Ogri''la (ogres transcended through apexis crystals, aided by the Sha''tari Skyguard); npc_text 10926 (Chu''a''lor: crystals, peace, demons, ethereals, Black Dragonflight); quest 11025 reward text (left and right heads); npc_text 10919 (Kronk: you only have one head); quest 11009 description (Ogri''la in the heavens above); quest 11030 and 11010 descriptions (flying mount); quest 11062 description and reward text (Skyguard Outpost to the north, built with me own hands, missions for mutual protection); npc_text 10906 (Keller''s eyepatch)'),
(352222, 1, 3522, 22, 0, 0, 'Vortex Pinnacle', 'Vortex Pinnacle crowns the western terrace around Ogri''la, a field of crystal formations among the relics of the Apexis, a vanished sect of arakkoa who once lived atop these mountains. Their relics still answer those who master their sequences of colored light, and gan''arg analyzers of the Legion pick over them for secrets. Aether rays drift overhead, coveted by the Skyguard as mounts. The ghost of an arakkoa elder, Sai''kkal, lingers here, his sight so dim that he peers at every visitor as though hoping to know them. The black dragons Rivendark and Obsidia rule the skies of this terrace from their perches, a constant menace to Ogri''la.', 'quest 11058 description (Apexis, extinct sect, relics with colored sequences); quest 11025 request text; DB spawns in 3832: Apexis Relic, Apexis Monument, Gan''arg Analyzer, Aether Ray; quest 11065 description (aether rays around Vortex Pinnacle as remounts); quest 11078 description (Rivendark and Obsidia lord over this terrace, perches); npc_text 10794 (Sai''kkal cannot see clearly; default gossip); DB displays: Rivendark 24139 and Obsidia 12869 use black dragon skins; npc_text 10926 (the Black Dragonflight threatens Ogri''la)'),
(352223, 1, 3522, 23, 0, 0, 'Forge Camps Wrath and Terror', 'Two Burning Legion forge camps flank the western terrace, Forge Camp: Wrath to the north and Forge Camp: Terror to the south. Their flak cannons, fed from stacks of fel cannonballs, shoot down Skyguard riders left and right, and in each camp a fel crystalforge pours out green smoke as it turns apexis shards into unstable flasks. Demon chieftains such as Galvanoth and Braxxus answer when shards are offered at the camps'' burning fel crystal prisms. On the southern border of Wrath the demons have raised Shartuul''s Transporter, an experimental gate meant to expand the camp, which the ogres of Ogri''la fear will soon crush them.', 'quest 11010 description (Wrath and Terror to the north and south, fel cannons shooting down the Skyguard); DB spawns in 3785: Legion Flak Cannon, Fel Cannonball Stack; quest 11030 description (fel crystalforge at either forge camp, green smoke, ten apexis shards); quest 11079 description (demon chiefs at fel crystal prisms: Galvanoth, Braxxus, Zarcsin, Mo''arg Incinerator); quest 11026 reward text (special transporter on their southern border, experimental gate to expand the forge camp); quest 11060 request text (the camp growing bigger, soon too big and crush us)'),
(352224, 1, 3522, 24, 0, 0, 'Bash''ir Landing', 'The northernmost shelf of the mountains holds Bash''ir Landing, a settlement of the Ethereum named for Bash''ir and his followers. In great stasis chambers they keep ferocious beasts gathered from many worlds, which they hope one day to command, and they smuggle mana cells out of Tempest Keep for Kael''thas. A crystalforge stands at the landing''s northeast corner, and every few hours Skyguard aether-techs fly in to raid it. East of the landing rises the Crystal Spine, where felstorm corruptors and infernals of the Legion roam among Apexis relics, and the black dragons Insidion and Furywing rule the skies from their perches.', 'quest 10974 description (Ethereum settlement on the northernmost shelf); warcraft.wiki.gg/wiki/Bash''ir_Landing (named for Bash''ir and his subdivision of the Ethereum; Skyguard assaults every two hours); quest 10974 reward text (beasts from many worlds, hope to command them); quest 11513 description (ethereals smuggling mana cells out of Tempest Keep for Kael''thas); quest 11061 description (crystalforge at the northeast corner); quest 11119 description; DB spawns in 3865: Felstorm Corruptor, Darkflame Infernal, Apexis Relic; quest 11078 description (Insidion and Furywing rule the terrace to the northeast); DB displays: Insidion and Furywing 12869, black dragon skins; AreaTable 3864 name Bash''ir Landing (wiki trivia: the non-possessive form is correct)'),
(352230, 2, 3522, 1, 2, 0, 'Rexxar', 'Rexxar, Champion of the Horde, is Mok''Nathal, of mixed orc and ogre blood, and the son of Leoroxx. Thirty years ago he left his people against his father''s wishes to follow the Horde to Azeroth, where he roamed with his bear Misha and once took Thrall''s place at a summit that proved to be an ambush. Now he has crossed the Dark Portal, chasing rumors of his people across Outland. At Thunderlord Stronghold he carries that search, the struggle against the Alliance and the war with the ogres and their gronn masters. With Misha, his hawk Spirit, his boar Huffer and his wyvern Leokk, he means to break the sons of Gruul and prove himself his father''s true son.', 'quest 10709 description and reward text (my son; left thirty years ago to follow the Horde to Azeroth); quest 10614 description (rumors across Outland); npc_text 10661 (Rexxar); warcraft.wiki.gg/wiki/Thunderlord_Stronghold (Rexxar came seeking his race); quests 10714, 10721, 10723 (Spirit, Huffer, Misha); quest 10724 (Leokk); quest 10742 reward text (true son); warcraft.wiki.gg/wiki/Rexxar (Warcraft III: The Frozen Throne, 2003: volunteered to go to the summit in Thrall''s place; bear Misha); warcraft.wiki.gg/wiki/Razor_Hill (the Kul Tiran summit was a planned ambush; Rexxar went in Thrall''s place and defeated the assassins)'),
(352231, 2, 3522, 2, 2, 0, 'Leoroxx', 'Leoroxx leads the Mok''Nathal of the eastern village and is father to Rexxar, though he will not call him one of his people. He opposed Rexxar''s departure with the Horde thirty years ago and has never forgiven it: to Leoroxx, being born a half-breed does not make one Mok''Nathal, and his son is not welcome. He judges outsiders just as harshly. Those who would understand his people must share their struggle, slaying Vekh of the Vekh''nir, Gnosh Brognat of the Bladespire Outpost and Dreadwing, mother of the Singing Ridge''s nether drakes, and even then he warns that they do not yet know what it is to be Mok''Nathal.', 'quest 10709 description; quest 10709 reward text (Leoroxx staunchly against his leaving); warcraft.wiki.gg/wiki/Leoroxx; quests 10846, 10843, 10845 descriptions and reward texts'),
(352232, 2, 3522, 3, 0, 0, 'Baron Sablemane', 'Baron Sablemane waits outside the Circle of Blood, a master of the alchemical arts whose loathing of interruptions is surpassed only by his hatred of Gruul the Dragonkiller and his seven sons. He will help those who fight the gronn, but always for a price, because, as he puts it, free things destroy friendships. He brews poisons from crust burster venom and fashions traps from the essence of dragon fire. The clues are there for those who look: the gronn slaughtered his people and his children, a pet dragon carries his messages, and his agent Samia Inkling aids the druids against the Wyrmcult at his behest. Few learn that he is a black dragon in a human guise.', 'npc_text 10603 (Sablemane gossip); quest 10783 description (master of the alchemical arts); quest 10715 description (free things destroy friendships); quests 10785, 10801 (they slaughtered my people, my children; dragon fire trap); quest 10818 description (pet dragon); npc_text 10538 (Samia, at the behest of her master Baron Sablemane); quest 10806 reward text (transformation, true identity); warcraft.wiki.gg/wiki/Baron_Sablemane (human disguise of a black dragon); DB: Baron Sablemane 22103 uses human male display 20807; his battle form Sabellian 22496 uses display 21079 with black dragon skins'),
(352233, 2, 3522, 4, 0, 0, 'Gruul the Dragonkiller', 'Gruul the Dragonkiller is the greatest of the gronn and the master of the Blade''s Edge Mountains, worshiped as a god by the ogres who live there. When Deathwing''s black dragons nested in these lands, Gruul led the gronn and ogres against them; the Bladespire tore the dragons from the sky with their incantations, and Gruul impaled the bodies on the spires of Dragons'' End. The ogre clans now fight one another for his favor, which rests with the Bladespire, and his seven sons enforce his will across the mountains and as far as Nagrand. He keeps to his lair in the north beside High King Maulgar, the old ogre king, whom his enemies call his puppet.', 'warcraft.wiki.gg/wiki/Gruul (war on the black dragonflight, Bladespire incantations, impaled on the spires, worshiped by the ogres of Blade''s Edge, seven sons); quests 10504, 10505 descriptions and request texts (clans vie for the favor of Gruul the Dragonkiller); nagrand.json 351831 (Durn in Nagrand); quest 11000 reward text (Gruul and his puppet, the old king, Maulgar)'),
(352234, 2, 3522, 5, 0, 0, 'The Sons of Gruul', 'Gruul has seven sons, and they are the true power behind the ogre wars of Blade''s Edge. Goc commands the Bladespire from his altar outside his father''s lair. Gorgrom the Dragon-Eater accepts sacrifices at Boulder''mok and quietly drives the Bloodmaul against their neighbors. Grulloc, dim-witted, hatches his schemes in the Cursed Hollow, and Maggoc patrols the eastern ranges as their warden. Skulloc Soulgrinder, trained by the ogre warlock Vim''gol the Vile, hides in a barrow near the lair. Slaag went into exile among the Gordunni ogres above Shattrath, and Durn the Hungerer hunts the fields of Nagrand. Mog''dorg the Wizened believes no ogre will be free until all of them are dead.', 'warcraft.wiki.gg/wiki/Gruul (seven sons named); quests 10742, 10806 (Goc, master of the Bladespire, altar outside Gruul''s Lair); quests 10723, 10798 (Gorgrom at Boulder''mok, behind the Bloodmaul plans); quests 10721, 10995 (Grulloc); quest 10996 (Maggoc, warden of the eastern range); quest 10998 (Skulloc trained by Vim''gol); quest 10997 (Slaag exiled among the Gordunni); nagrand.json 351831 (Durn); quest 11000 reward text; quests 10742, 10806 RequiredNpcOrGo 20555 (Goc summoned at his altar, Horde and Alliance); quests 10723, 10802 (Gorgrom summoned at his altar, Horde and Alliance); quest 11000 (Skulloc forced out at the barrow, open to all)'),
(352235, 2, 3522, 6, 0, 0, 'Mog''dorg the Wizened', 'Mog''dorg the Wizened is a Bloodmaul ogre who stands atop a tower outside the Circle of Blood and speaks with a clarity no other ogre below can match. The gift came from a staff given him by the ogres of Ogri''la, whose crystal sharpened his mind. He has used it to build a secret society, an underground resistance against the gronn, for he believes his clan faces annihilation at the hands of the Bladespire and the sons of Gruul who back them. He sent the ogre Grok to Shattrath to beg for help, and dreams of a home where ogres may decide their own destiny. Not all ogres trust him: the wandering speaker Mar''grom calls Ogri''la a myth.', 'npc_text 10800, 10860 (resistance; staff from Ogri''la); quest 10983 description and reward text (sent Grok to the city); quests 10989, 11057 reward texts; quest 10996 reward text (home for the ogres, own destiny); creature_text 18693 (Speaker Mar''grom)'),
(352236, 2, 3522, 7, 1, 0, 'Toshley', 'Toshley is the gnome inventor who brought a whole band of scientists to Outland, with Razak''s Roughriders hired to guard them. They first settled with the night elves at Sylvanaar, but their machines and experiments made a mess of the Living Grove, and the elves sent them away, which Toshley counts a blessing. He left a remote sentry, R-3D0, on the Jagged Ridge to turn visitors away, along with a trail of spare parts leading straight to his door. At his station he runs hair-raising projects, capturing electromentals and charging spheres with lightning from wild serpents, and cheerfully tells volunteers the odds that they would implode.', 'quest 10580 description (driving Toshley and his gnome friends away); npc_text 10423 (glad to be rid of those stuffy elves); quest 10620 description (hired on to help Toshley when he decided to move to Outland); quests 10580 reward and 10581 description (R-3D0, trail of spare parts); quest 10584 description (electromentals); quest 10657 description and reward text (lightning, 23.72 chance of imploding)'),
(352237, 2, 3522, 8, 0, 0, 'Tree Warden Chawn', 'Tree Warden Chawn, a tauren of the Cenarion Expedition, leads Evergrove. He came to the Ruuan Weald to restore the balance of nature to the mountains and finds the arakkoa and the Wyrmcult making that task hard. Chawn prefers to begin with talk. When the cultists began logging and poaching in the weald, he offered their overseer a compromise and was refused out of hand, and only then did he set his allies on the hewers. He is quick to sense evil in an object, freely admits he is no military planner, and gladly accepts help, whether from passing travelers or from the scholar Samia Inkling.', 'warcraft.wiki.gg/wiki/Evergrove (Tree Warden Chawn, tauren, leader); npc_text 10534; quest 10682 description and reward text; quest 10713 description; quest 10825 request and reward texts (senses evil); quest 10894 description (not much of a military planner)'),
(352238, 2, 3522, 9, 2, 0, 'T''chali the Witch Doctor', 'T''chali the Witch Doctor is a troll who came down into Bloodmaul Ravine to teach the ogres to brew. The Bloodmaul were losing their war with the Bladespire, so he set out to create the perfect brew, one that would strengthen its drinker and weaken the enemy. His thanks was to be buried in the ravine and left to rot, with Grimnok Battleborn leading the burial, and the next day Korgaah came raiding from the Bladespire to kick him in the head. The ogres even stole his hookah. T''chali still speaks from his grave, and his thirst for revenge on both clans is far from quenched.', 'quest 10542 description; quest 10545 description (perfect brew, strengthens you and weakens your enemy); quest 10543 description (Grimnok led the burial, Korgaah came south to raid); quest 10543 reward text and 10544 description (powerful witch doctor in life, revenge not quenched)'),
(352250, 3, 3522, 1, 2, 0, 'Rexxar''s Kin', 'Among the Bladespire, Horde fighters find a Thunderlord clan artifact and bring it to Rokgah Bloodgrip, a scholar of that fallen clan. He seeks a drum, an arrow and a tablet lost when the Bladespire were driven from Thunderlord Stronghold, and with a fragment of his own fiery soul he sends a seeker''s spirit flying to find the last relic, the Thunderspike, hidden at the back of the Draenethyst Mine. With the relics returned to appease the stronghold''s dead, the ghost of Garm Wolfbrother, last chieftain of the Thunderlord, appears with news for Rexxar: the Mok''Nathal live in a village east beyond the Razor Ridge, and they are in danger. Rexxar, uneasy about how his people will greet him, sends an envoy to Leoroxx, who coldly admits that Rexxar is his son and wants nothing to do with him. Rexxar resolves to open his father''s eyes. His hawk Spirit, sent to spy on the Bloodmaul leaders, learns that the sons of Gruul are driving the ogres to destroy the Mok''Nathal.', 'quests 10524, 10525, 10526 (descriptions and reward texts); npc_text 10322 (Rokgah); quest 10718 description and reward text (Garm, last chieftain of the Thunderlord); quest 10614 description; quest 10709 description and reward text; quest 10714 description and reward text; warcraft.wiki.gg/wiki/Garm_Wolfbrother'),
(352251, 3, 3522, 2, 0, 0, 'Baron Sablemane''s Price', 'Rexxar and Commander Haephus Stonewall, Sylvanaar''s envoy at Evergrove, both need a weapon that can kill a gronn, and both turn to Baron Sablemane. For the Alliance the trail begins with Dorgok of Bloodmaul Camp, whose corpse yields a statuette of Gorgrom the Dragon-Eater, proof that the gronn is behind the Bloodmaul plans against Sylvanaar; for the Horde, Rexxar wants a poison for the Bloodmaul kegs, carried in by a marmot. Either way the work runs the same: venom glands from the crust bursters of the Churning Gulch, then the sack Grulloc guards in the Cursed Hollow as the baron''s price, stolen while the gronn sleeps under a powder or chases Rexxar''s boar. Satisfied, he crafts a trap of dragon fire. Set at Gorgrom''s altar at Boulder''mok, it brings down the Dragon-Eater, and grisly totems of his worshippers'' heads are planted around the body. Last comes Goc, master of the Bladespire, slain at his altar outside Gruul''s Lair beside Rexxar, or beside Sablemane himself, who sheds his human guise in the battle.', 'quests 10783, 10715, 10749, 10720, 10721, 10785, 10723, 10724, 10742 (Horde); quests 10795, 10797, 10798, 10799, 10800, 10801, 10802, 10818, 10805, 10806 (Alliance); npc_text 10612 (Stonewall representing Sylvanaar at Evergrove)'),
(352252, 3, 3522, 3, 0, 0, 'The King of the Ogres', 'Mog''dorg the Wizened leads a secret resistance among the Bloodmaul, convinced his clan will be wiped out by the Bladespire and the sons of Gruul who back them. Those he trusts are sent against the gronn one by one. Grulloc dies in the Cursed Hollow for the dragon skull he treasured, and Maggoc on the Razor Ridge for the treasure chest he carries, which turns out to be empty. Even Slaag, who exiled himself among the Gordunni ogres above Shattrath, must fall, lest he return. The last, Skulloc Soulgrinder, stays hidden, so the grimoire of his teacher, the warlock Vim''gol the Vile, is taken from the fire circle where Vim''gol is summoned, and its ritual is read aloud at Soulgrinder''s Barrow, forcing Skulloc into the world while his ghostly victims try to smash the Soulgrinder. With the sons dead, Mog''dorg declares the ogres freed from their shackles. Bloodmaul and Bladespire alike gather to hail their liberator as a new king, while Gruul and Maulgar cower in their lair, and the new monarch is sent up to Ogri''la.', 'quests 10989, 11057 reward texts; quest 10995 description and reward text; quest 10996 description and reward text; quest 10997 description; quest 10998 description; quest 11000 description and reward text; quest 11009 description; creature_text 22941 (All hail the new king)'),
(352253, 3, 3522, 4, 0, 0, 'Ogre Heaven', 'The ogres of Ogri''la are newly wise and wish only for peace, but they are beset on every side. Chu''a''lor teaches visitors about the Apexis shards that every creature on the terraces covets, named for a vanished arakkoa civilization, and about the relics that reward those who master their sequences of light, while the larger monuments summon crystal guardians that long ago turned on their arakkoan makers. The weary father Torkus wants two unstable flasks, from a forge camp and from Bash''ir''s Landing, so that one of his ten sons can join the Sha''tari Skyguard. At the Skyguard Outpost nearby, Sky Commander Keller and his sharp-tongued sergeant Vanderlip send riders to bomb the fel cannonball stacks of the forge camps, Skyguard Khatie wants aether rays roped as remounts, and the dragons of the terraces must be lured from their perches by breaking open their eggs. Kronk''s banishing crystal sends slain demons back where they came from, and Gahk dreams of smashing the demons'' transporter.', 'quest 11025 description and request text; quests 11058, 11059; quests 11030, 11061 descriptions, npc_text 10916 (ten sons); quest 11062 reward text (Vanderlip''s sharp tongue); quests 11010, 11102; quests 11065, 11066; quest 11078 description; quest 11026 description and reward text; npc_text 10923 (Gahk)'),
(352254, 3, 3522, 5, 0, 0, 'The Souls of Razaan''s Landing', 'Gnomes from Toshley''s Station have been vanishing on the road north, and at Mok''Nathal Village the spiritcaller Dohgar senses a great deal of pain coming from the ethereals'' direction. Both turn their eyes to the small pink orbs that drift above Razaan''s Landing. Toshley, curious about the Razaani''s technology, sends a trap to catch a few; Dohgar, who has already set free the twisted spirits of the Singing Ridge''s nether drakes, plants totems to draw them in. The answer horrifies them both. The orbs are woven from nether energy and souls, some of them gnomes and some of them Mok''Nathal ancestors. Toshley demands the death of Nexus-Prince Razaan, and Leoroxx, trusting his spiritcallers, names it a defilement. Razaan is drawn out by the slaughter of his followers and slain, his collection of souls is carried off, and at Mok''Nathal Village the ancestors are released at last to the cleansing fire.', 'quests 10620, 10671 (missing people); quests 10674, 10675 (Toshley); quests 10853 reward text, 10859, 10865, 10867 (Dohgar and Leoroxx)'),
(352255, 3, 3522, 6, 0, 0, 'Brew and Banner', 'Every ogre clan in Blade''s Edge fights the others for Gruul''s favor, and the newcomers have learned to use the feud. At Sylvanaar the dwarf Borgrim Stouthammer, on holiday with the Explorers'' League after the dirt and insects of Silithus, sends for Bloodmaul brew, finds it vile, and has the rest poured down Bladespire throats to see what happens. Vindicator Vuuleen, caged by choice inside Bladespire Hold to spy on the clan, wants back the sword and shield its leaders took, then sends his helpers against the chieftain Gorr''Dim, and at last has a stolen Bladespire banner planted atop the Bloodmaul''s Northmaul Tower, so that Bloodmaul fury falls on Bladespire Hold instead of Sylvanaar. The Horde''s guide in the feud is a dead troll. T''chali, buried by the Bloodmaul he taught to brew, wants his hookah back, tests his brew on the Bladespire, has Grimnok Battleborn and Korgaah killed, and then curses the buildings of both clans with a fetish from his grave.', 'quests 10504, 10505 request texts (clans vie for Gruul''s favor); quests 10510 request text, 10511, 10512 (Stouthammers, vacation, Silithus); quests 10516, 10517, 10518; quests 10542, 10545, 10543, 10544'),
(352256, 3, 3522, 7, 0, 0, 'The Blackwing Coven', 'When the Wyrmcult began felling the trees of the Ruuan Weald and slaughtering its wildlife, Tree Warden Chawn sent an envoy to their overseer, Nuaar, offering compromise. Nuaar answered that his people were free to do as they pleased, and Chawn turned to force, setting his allies on the hewers. A bloodstained note taken from a cultist then revealed a planned meeting between Nuaar and Kolphis Darkscale, second in command at the Blackwing Coven. Watcher Moonshade, holding the Wyrmskull Tunnel against the massing cultists, first wants their leader Draaca Longtail dead; then an agent of Evergrove enters the coven disguised as Nuaar. Kolphis berates the false overseer for the trickle of lumber and livestock, and lets slip that Maxnar the Ashmaw means to wipe out the druids, while Kolphis himself has arranged a truce with the arakkoa so the cult need not fight on another front. The Expedition strikes first. Samia Inkling has the coven''s blackwhelps netted alive for study, and Maxnar the Ashmaw is slain in his caverns.', 'quests 10682, 10713; npc_text 10533 (Nuaar: no negotiations); quests 10719, 10894, 10893, 10722; npc_text 10541, 10542, 10543 (Kolphis meeting); creature_text 21983 (second-in-command); quests 10717, 10747, 10748'),
(352257, 3, 3522, 8, 0, 0, 'Whispers of the Raven', 'The arakkoa of Blade''s Edge were long a quiet people, their cult of the Raven a gathering of misfits and madmen. That has changed, and every power in the mountains wants to know why. Dertrok of the Mok''Nathal studies the crystals the Vekh''nir charge at their spell circles, tests their power on the ogre slaves of Trogma''s Claim, and sends his findings to Timeon at Evergrove; at Sylvanaar, Daranelle has a visitor cast a Lashh''an feather spell and finds it a strange communion. Timeon wants a pendant from the Harbingers of the Raven, heralds of the Ruuan''ok, and with its power the speech of the Grishna can be understood at their four shrines. Their prophecies of a raven rising from the darkest night trouble him deeply. Meanwhile an orb taken from a Grishna shows Chawn that the arakkoa have set spirits to possess the trees of the Raven''s Wood, and the ancient Treebole calls for an exorcism to free them.', 'quests 10565, 10566, 10615 (Dertrok, Horde); quests 10555, 10556 (Daranelle, Alliance); quests 10567, 10607 (Timeon; peaceful for a long time, misfits and madmen); broadcast_text 19475; quests 10825, 10829, 10830'),
(352258, 3, 3522, 9, 0, 0, 'The Hounds of Death''s Door', 'A damaged mask taken from a fel corrupter in the Bladed Gulch still murmurs with strange sounds. O''Mally Zapnabber at Evergrove mends it and finds it a Legion communication device, a Felsworn gas mask that Wildlord Antelarion has long wanted. Wearing it, an agent slips into Forge Camp: Anger and speaks through the Legion communicator, telling the enraged demon on the other end that the camp has revolted. He orders every traitor silenced, so the camp''s engineers and attendants are cut down on his behalf, and then the blame is laid on his underling Doomcryer, long suspected of undermining him, who is summoned through the camp''s five obelisks and slain. Antelarion then turns to a greater danger. At Death''s Door, Evergrove druids imbue fel cannonballs with nature''s wrath, the Legion''s own fel cannons are turned on the two warp-gates that strengthen the void terrors, and Baelmon the Hound-Master, keeper of the portal''s ritual, falls with the druids'' help.', 'quests 10810, 10812, 10819, 10820, 10821; quests 10910, 10904, 10911, 10912; item 31384 Damaged Mask dropped by Fel Corrupter 21300'),
(352259, 3, 3522, 10, 0, 0, 'The Stasis Chambers of Bash''ir', 'The trail of the Ethereum''s prisoners leads Commander Ameer of the Protectorate from Netherstorm to Bash''ir Landing, where an image of the commander waits. Evidence from Stasis Chamber Alpha confirms his fears: these larger prisons hold ferocious beasts and creatures from many different worlds, which the Ethereum mean one day to command. Ameer resolves to destroy them all, forging keys from captured prison keys so that each chamber can be opened and whatever lurks within destroyed. Among the spoils may be a Mark of the Nexus-King, the last piece of a key to the stasis chambers hidden in the Mana-Tombs of Auchindoun. The Sha''tari Skyguard has its own business here. Every couple of hours Sky Commander Keller''s aether-techs launch an assault on the landing''s crystalforge, which they prefer to call research, and those who keep the ethereals off them long enough may buy the surplus the crystalforge yields.', 'quest 10974 description and reward text; quest 10975 request and reward text; quest 10976 description; quest 10977 description; quest 11119 description and reward text; netherstorm.json 352340 (the trail leads to Bash''ir''s Landing)');
